import java.util.*;

class Solution {
    public int fewestFixes(String src, String dst) {
        int n = src.length(), m = dst.length();
        int[] prev = new int[m + 1];
        for (int j = 0; j <= m; j++) prev[j] = j;           // "" -> dst[:j] needs j inserts
        for (int i = 1; i <= n; i++) {
            int[] cur = new int[m + 1];
            cur[0] = i;                                     // src[:i] -> "" needs i deletes
            for (int j = 1; j <= m; j++) {
                if (src.charAt(i - 1) == dst.charAt(j - 1)) cur[j] = prev[j - 1];
                else cur[j] = 1 + Math.min(prev[j - 1], Math.min(prev[j], cur[j - 1]));
            }
            prev = cur;
        }
        return prev[m];
    }
}

