class Solution:
    def fewestFixes(self, src: str, dst: str) -> int:
        m = len(dst)
        prev = list(range(m + 1))
        for i in range(1, len(src) + 1):
            cur = [i] + [0] * m
            for j in range(1, m + 1):
                if src[i - 1] == dst[j - 1]:
                    cur[j] = prev[j - 1]
                else:
                    cur[j] = 1 + min(prev[j - 1], prev[j], cur[j - 1])
            prev = cur
        return prev[m]

