function fewestFixes(src, dst) {
  const n = src.length, m = dst.length;
  const dp = Array.from({length: n + 1}, (_, i) => Array.from({length: m + 1}, (_, j) => i === 0 ? j : (j === 0 ? i : 0)));
  for (let i = 1; i <= n; i++) for (let j = 1; j <= m; j++)
    dp[i][j] = src[i-1] === dst[j-1] ? dp[i-1][j-1] : 1 + Math.min(dp[i-1][j-1], dp[i-1][j], dp[i][j-1]);
  return dp[n][m];
}
